 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the full-height/full-width grid separators.
    sep = next(c for c in range(1, 10)
               if any(all(v == c for v in row) for row in grid)
               and any(all(grid[i][j] == c for i in range(h)) for j in range(w)))
    rs = [i for i, row in enumerate(grid) if all(v == sep for v in row)]
    cs = [j for j in range(w) if all(grid[i][j] == sep for i in range(h))]
    rb, cb = [-1] + rs + [h], [-1] + cs + [w]
    cells = [[(rb[a] + 1, rb[a + 1], cb[b] + 1, cb[b + 1])
              for b in range(len(cb) - 1)] for a in range(len(rb) - 1)]

    # The left panel in each horizontal band gives that band's output color.
    colors = []
    for band in cells:
        i0, i1, j0, j1 = band[0]
        colors.append(next(grid[i][j] for i in range(i0, i1) for j in range(j0, j1)
                           if grid[i][j] not in (0, sep)))

    # A non-key panel contains the pattern to reproduce in every panel.
    shape = None
    for band in cells:
        for i0, i1, j0, j1 in band[1:]:
            pts = [(i - i0, j - j0) for i in range(i0, i1) for j in range(j0, j1)
                   if grid[i][j] not in (0, sep)]
            if pts:
                shape = (i1 - i0, j1 - j0, pts)
                break
        if shape:
            break
    if shape is None:
        return [row[:] for row in grid]

    out = [[sep if grid[i][j] == sep else 0 for j in range(w)] for i in range(h)]
    _, _, pts = shape
    for band_index, band in enumerate(cells):
        color = colors[band_index]
        for i0, i1, j0, j1 in band:
            for dr, dc in pts:
                if dr < i1 - i0 and dc < j1 - j0:
                    out[i0 + dr][j0 + dc] = color
    return out
